P = [
 dict(pmid='43029715', doi='10.3390/s26216914', journal='Sensors (Basel)', title='Long-Term Field Performance of Sensirion SEN54 and SPS30 Low-Cost Particle Sensors: Seasonal Variability and Correction Using Dew Point Deficit.', short='CHMI Prague Sensirion SEN54 SPS30 vs Fidas 200S 19 months dew point deficit MARS correction PM10 dust', design='Long-term field measurement campaign', pm='PM2.5 and PM10 from two SEN54 and two SPS30 OPCs against a Palas Fidas 200S equivalent monitor', geo='Czech Republic', endpoint='R2 and RMSE versus equivalent monitor before and after humidity correction', tier='A', basis='Low-cost sensor / network', affil='Czech Hydrometeorological Institute, Czech Republic; Czech Hydrometeorological Institute, Czech Republic', n='Two pairs of Sensirion OPCs (SEN54, SPS30) co-located with a Fidas 200S for 19 months. Raw agreement was far worse for PM10 (mean R2 0.50, RMSE 13.70 ug/m3) than PM2.5 (R2 0.87, RMSE 5.53 ug/m3); no unit captured mineral-dust PM10 episodes. Performance was better in the cold season and much of the seasonal variation tracked dew point deficit; MARS models with sensor PM and DPD raised PM10 to R2 0.68 (RMSE 8.25) and PM2.5 to R2 0.92 (RMSE 3.29), with particle counts helping the SPS30 further. Four sensors at one site; residual warm-season underestimation remains unexplained, and the Fidas is itself an optical equivalent rather than gravimetric. Relevance: direct - dew point deficit is a cheap, transferable humidity covariate; the PM10 dust blind spot is not fixed by it.', sub=corpus.SENS),
 dict(pmid='43029518', doi='10.3390/s26216718', journal='Sensors (Basel)', title='Software-Based Relative Humidity Compensation for Low-Cost Optical PM Sensors Using Machine Learning: A Case Study from Upper Silesia, Poland.', short='University of Silesia SDS011 unheated vs heated software humidity compensation polynomial SVR DNN LSTM latency', design='Calibration model comparison', pm='PM2.5 from an unheated SDS011 with T, RH, P, targeting a co-located heated SDS011', geo='Poland (Upper Silesia)', endpoint='R2, MAE, RMSE against the heated sensor; inference latency', tier='B', basis='Low-cost sensor / network', affil='University of Silesia, Poland; University of Silesia, Poland', n="48,860 10-min records in Upper Silesia: six ML models trained to make an unheated SDS011 plus T, RH and pressure emulate a co-located heated SDS011. Sixth-degree polynomial, SVR and dense networks reached R2 94%, MAE 1.41-1.61 and RMSE 3.69-3.79 ug/m3 for PM2.5; LSTM was worse (R2 88%, MAE 2.56, RMSE 5.33) and over 500 times slower at inference (0.1215 ms/sample). The target is another low-cost sensor, so the work reproduces the heater's behaviour, not reference-grade mass; a heated inlet also evaporates semi-volatile material, so the target is biased in its own right. Single site and sensor pair. Relevance: direct - supports static non-linear RH correction on microcontrollers, but needs validation against FEM data before it substitutes for calibration.", sub=corpus.SENS),
 dict(pmid='43029501', doi='10.3390/s26216701', journal='Sensors (Basel)', title='WSN-IoT-Based Mobile Environmental Monitoring System for Smart Cities.', short='Universidad del Magdalena mobile WSN-IoT node edge fog cloud PM2.5 PM10 CO2 MQTT TRL 6 Santa Marta', design='Instrument development and laboratory validation', pm='PM2.5 and PM10 from a mobile low-cost sensor node (sensor model not stated in abstract)', geo='Colombia', endpoint='System function (TRL 6) and RMSE after validation', tier='C', basis='Low-cost sensor / network', affil='Universidad del Magdalena, Colombia; Universidad del Magdalena, Colombia', n='Engineering paper describing a mobile environmental node (precipitation, PM2.5, PM10, CO2, irradiance, T, pressure, wind) with a fixed sink, edge-fog-cloud architecture, MQTT broker and web interface with geospatial queries. Store-and-forward, integrity checks and flow control are built in; laboratory and field tests reached TRL 6. Metrological evaluation against independent validation reduced RMSE for four of six variables, most for PM2.5, but no numbers are given in the abstract. No sensor model, reference instrument, duration or mobile-sampling design is reported, so the PM data quality cannot be judged from the abstract. Relevance: direct but thin - an architecture template for mobile low-cost PM mapping, without the calibration evidence needed to use its data.', sub=corpus.SENS),
 dict(pmid='43028120', doi='10.3390/ijms27219869', journal='Int J Mol Sci', title='Association Between Ambient PM2.5 Exposure and Leukocyte Telomere Length Among Rural Adults: Cross-Sectional Study in Northern Thailand.', short='Chiang Mai rural adults biomass burning PM2.5 lag 0-90 d leukocyte telomere length 8-OHdG wild cluster bootstrap', design='Cross-sectional study', pm='Ambient PM2.5 cumulative averages over lag 0-7 to 0-90 days (source not stated in abstract)', geo='Thailand (northern)', endpoint='Relative leukocyte telomere length (qPCR T/S); 8-OHdG, SII, SIRI', tier='B', basis='Not stated', affil='Chiang Mai University, Thailand; Chiang Mai University, Thailand', n="179 rural adults in biomass-burning northern Thailand; PM2.5 averaged over five windows up to the blood draw. Positive associations with telomere length appeared only for the 0-30, 0-60 and 0-90 day windows: per window-specific IQR (8.13 and 7.25 ug/m3) relative LTL was 0.050 T/S higher (95% CI 0.012-0.089) at 0-30 days and 0.079 (0.035-0.123) at 0-60 days. Crucially, the authors' own wild cluster bootstrap over eight site-date groups left none of the five associations significant (p 0.247-0.787); the standard errors ignore site-date clustering, and p-values are unadjusted. Longer telomeres with more PM run against the usual hypothesis. Relevance: indirect - exposure varies by only eight site-date clusters, so the effective sample is eight; personal or sensor-resolved exposure is what this design lacks.", sub=corpus.MECH),
]
